463	func (c *MigrationTargetController) sync(vmi *v1.VirtualMachineInstance, domain *api.Domain) error {
464		oldSpec := vmi.Spec
465		oldStatus := vmi.Status
466		oldLabels := vmi.Labels
467		vmi = vmi.DeepCopy()
468	
469		// post-migration clean up
470		if vmi.Status.MigrationState != nil && vmi.Status.MigrationState.EndTimestamp != nil &&
471			(vmi.Status.MigrationState.Completed || vmi.Status.MigrationState.Failed) {
472			return c.finalCleanup(vmi, &oldSpec, &oldStatus, oldLabels, domain)
473		}
474	
475		if domain != nil {
476			c.logger.Object(vmi).Infof("VMI is in phase: %v | Domain status: %v, reason: %v", vmi.Status.Phase, domain.Status.Status, domain.Status.Reason)
477		} else {
478			c.logger.Object(vmi).Infof("VMI is in phase: %v | Domain does not exist", vmi.Status.Phase)
479		}
480	
481		syncErr := c.processVMI(vmi)
482		if syncErr != nil {
483			c.recorder.Event(vmi, k8sv1.EventTypeWarning, v1.SyncFailed.String(), syncErr.Error())
484			// `syncErr` will be propagated anyway, and it will be logged in `re-enqueueing`
485			// so there is no need to log it twice in hot path without increased verbosity.
486			c.logger.Object(vmi).Reason(syncErr).Error("Synchronizing the VirtualMachineInstance failed.")
487		}
488	
489		updateErr := c.updateStatus(vmi, domain)
490		if updateErr != nil {
491			c.logger.Object(vmi).Reason(updateErr).Error("Updating the migration status failed.")
492			return updateErr
493		}
494	
495		// If processVMI is just waiting for something to be ready, we can't and don't need to increase expectations.
496		// We can't because the VMI may not update before the thing is ready, deadlocking us
497		// We don't need to because every time processVMI is waiting for something it re-adds the key to the queue
498		updateVMIErr := c.updateVMI(vmi, &oldSpec, &oldStatus, oldLabels)
499		if updateVMIErr != nil {
500			return updateVMIErr
501		}
502	
503		c.logger.Object(vmi).V(4).Info("Target synchronization loop done.")
504		return syncErr
505	}
