//     by a "remove".
//   - Unchanged fields produce no operations.
//
// If newMS is nil the whole migration state is being removed, so a "test" asserting
// the original value followed by a "remove" is emitted for the base path.
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	if newMS == nil {
		patchSet.AddOption(
			patch.WithTest(migrationStateBasePath, origMS),
			patch.WithRemove(migrationStateBasePath),
